def diagnosis(err_train, err_dev, err_target):
    celah_bias = round(err_train - err_target, 6)
    celah_var = round(err_dev - err_train, 6)
    if celah_bias > celah_var:
        return "bias"
    if celah_var > celah_bias:
        return "variance"
    return "seimbang"

