import numpy as np

def error_rate(y_true, y_pred):
    y_true = np.asarray(y_true)
    y_pred = np.asarray(y_pred)
    return float(np.mean(y_true != y_pred))

import numpy as np

def prediksi(X, w, b):
    z = X @ w + b
    p = 1 / (1 + np.exp(-z))
    return p, (p >= 0.5).astype(int)

