def apakah_plateau(akurasi, toleransi):
    if len(akurasi) < 3:
        return False
    k1 = round(akurasi[-2] - akurasi[-3], 6)
    k2 = round(akurasi[-1] - akurasi[-2], 6)
    return bool(k1 < toleransi and k2 < toleransi)

